#include <zlib.h>
using namespace std;
struct Slice {const uint8_t* p; const uint8_t* e;};
uint64_t var(Slice& b) {uint64_t x=0; for(int i=0;i<10;i++){if(b.p>=b.e)throw runtime_error("varint EOF"); uint8_t v=*b.p++;if(i==9&&v>1)throw runtime_error("varint overflow");x|=uint64_t(v&127)<<(i*7);if(!(v&128))return x;}throw runtime_error("varint >10");}
struct F {int n,w; Slice s;uint64_t v;};
bool next(Slice& b,F& f){if(b.p>=b.e)return false;uint64_t tag=var(b);f.n=tag>>3;f.w=tag&7;f.v=0;f.s={nullptr,nullptr};if(f.n<1)throw runtime_error("field 0");if(f.w==0)f.v=var(b);else if(f.w==2){auto n=var(b);if(n>uint64_t(b.e-b.p))throw runtime_error("length exceeds message");f.s={b.p,b.p+n};b.p+=n;}else if(f.w==1||f.w==5){int n=f.w==1?8:4;if(b.e-b.p<n)throw runtime_error("fixed field trunc");f.s={b.p,b.p+n};b.p+=n;}else throw runtime_error("bad wire type");return true;}
string str(Slice s){return string((const char*)s.p,(const char*)s.e);}
string jsonescape(const string &x){string out;for(unsigned char c:x){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){char buf[8];snprintf(buf,sizeof(buf),"\\u%04x",c);out+=buf;}else out+=char(c);}return out;}
vector<uint8_t> ungzip(const vector<uint8_t>& in,size_t limit=24*1024*1024){z_stream z{};if(inflateInit2(&z,31)!=Z_OK)throw runtime_error("zlib init");z.next_in=(Bytef*)in.data();z.avail_in=in.size();vector<uint8_t> out;int rc=Z_OK;array<uint8_t,131072> tmp{};while(rc==Z_OK){z.next_out=tmp.data();z.avail_out=tmp.size();rc=inflate(&z,Z_NO_FLUSH);size_t n=tmp.size()-z.avail_out;if(out.size()+n>limit){inflateEnd(&z);throw runtime_error("gzip bomb");}out.insert(out.end(),tmp.data(),tmp.data()+n);}inflateEnd(&z);if(rc!=Z_STREAM_END)throw runtime_error("gzip invalid");return out;}
uint64_t read64(const uint8_t* p){uint64_t x=0;for(int i=0;i<8;i++)x|=uint64_t(p[i])<<(8*i);return x;}
struct Entry{uint64_t id,run,len,off;};
vector<Entry> directory(vector<uint8_t> data,int compression){if(compression==2)data=ungzip(data);else if(compression!=1)throw runtime_error("dir compression unsupported");Slice s{data.data(),data.data()+data.size()};auto n=var(s);if(n>2000000)throw runtime_error("index oversize");vector<Entry> entries(n);uint64_t current=0;for(auto &e:entries){current+=var(s);e.id=current;}for(auto &e:entries)e.run=var(s);for(auto &e:entries)e.len=var(s);uint64_t previous=0,prevlen=0;for(auto &e:entries){uint64_t encoded=var(s);e.off=encoded?encoded-1:previous+prevlen;previous=e.off;prevlen=e.len;}if(s.p!=s.e)throw runtime_error("trailing index");return entries;}
vector<uint8_t> section(ifstream& in,uint64_t offset,uint64_t length,size_t max=24*1024*1024){if(length>max)throw runtime_error("section exceeds size cap");vector<uint8_t> out(length);in.seekg(offset);in.read((char*)out.data(),out.size());if(in.gcount()!=static_cast<streamsize>(out.size()))throw runtime_error("section EOF");return out;}
struct Box{double w=1e300,s=1e300,e=-1e300,n=-1e300;void add(double w0,double s0,double e0,double n0){w=min(w,w0);s=min(s,s0);e=max(e,e0);n=max(n,n0);}};
struct Stats{uint64_t features[3]{},vertices=0,paths=0,names=0,review=0;Box box;vector<string> alerts;};
void zxy(uint64_t id,int& z,uint64_t& x,uint64_t& y){for(z=0;z<=22;z++){uint64_t stop=((1ULL<<(2*(z+1)))-1)/3;if(id<stop)break;}if(z>22)throw runtime_error("zoom above 22");uint64_t d=id-((1ULL<<(2*z))-1)/3;x=y=0;for(uint64_t s=1;s<(1ULL<<z);s*=2){uint64_t rx=1&(d/2),ry=1&(d^rx);if(ry==0){if(rx){x=s-1-x;y=s-1-y;}swap(x,y);}x+=s*rx;y+=s*ry;d/=4;}}
double lat(int z,double tiley){double n=double(1ULL<<z);return atan(sinh(M_PI*(1.-2.*tiley/n)))*180./M_PI;}
double lon(int z,double tilex){return tilex*360./double(1ULL<<z)-180.;}
void feature(Slice fb,const vector<string>& keys,const vector<string>& values,int extent,int z,uint64_t tx,uint64_t ty,Stats& st){
  vector<uint32_t> tags;int geomType=0;Slice geom{nullptr,nullptr};F fld;
  while(next(fb,fld)){if(fld.n==2&&fld.w==2){Slice t=fld.s;while(t.p<t.e)tags.push_back(var(t));}else if(fld.n==3&&fld.w==0)geomType=fld.v;else if(fld.n==4&&fld.w==2)geom=fld.s;}
  if(geomType<1||geomType>3||!geom.p)throw runtime_error("invalid feature type/geometry");
  int64_t x=0,y=0,minx=INT64_MAX,miny=INT64_MAX,maxx=INT64_MIN,maxy=INT64_MIN;bool moved=false,lined=false,closed=false;int ringsize=0;int np=0;
  auto valid=[&]{if(moved&&geomType==2&&!lined)throw runtime_error("line missing LineTo");if(moved&&geomType==3&&(!closed||ringsize<2))throw runtime_error("polygon ring unclosed");};
  while(geom.p<geom.e){uint64_t command=var(geom),op=command&7,repeat=command>>3;if(!repeat||(op!=1&&op!=2&&op!=7))throw runtime_error("geometry command invalid");if(op==1){if(geomType!=1&&repeat!=1)throw runtime_error("invalid MoveTo count");valid();st.paths++;moved=true;lined=closed=false;ringsize=0;}else if(op==2){if(geomType==1||!moved||closed)throw runtime_error("invalid LineTo");lined=true;ringsize+=repeat;}else{if(geomType!=3||repeat!=1||!moved||closed||ringsize<2)throw runtime_error("invalid ClosePath");closed=true;moved=false;continue;}for(uint64_t i=0;i<repeat;i++){int64_t dx=var(geom),dy=var(geom);x+=(dx>>1)^-(dx&1);y+=(dy>>1)^-(dy&1);if(llabs(x)>64*extent||llabs(y)>64*extent)throw runtime_error("outside safety buffer");minx=min(minx,x);maxx=max(maxx,x);miny=min(miny,y);maxy=max(maxy,y);np++;}}
  if(!np)throw runtime_error("empty geometry");valid();st.features[geomType-1]++;st.vertices+=np;
  double west=lon(z,tx+double(minx)/extent),east=lon(z,tx+double(maxx)/extent),north=lat(z,ty+double(miny)/extent),south=lat(z,ty+double(maxy)/extent);st.box.add(west,south,east,north);
  if(tags.size()%2)throw runtime_error("odd tags");for(size_t k=0;k<tags.size();k+=2){if(tags[k]>=keys.size()||tags[k+1]>=values.size())throw runtime_error("tag out of range");const auto &key=keys[tags[k]],&value=values[tags[k+1]];if(!value.empty()&&(key=="name"||key=="name_vi"||key=="name:vi"||key=="name_en"||key=="name_latin"||key=="adm0_name"||key=="adm1_name"||key=="adm2_name"||key=="admin_name"||key=="operator"||key.rfind("name:",0)==0)){st.names++;if(value.find("South China Sea")!=string::npos||value.find("Sansha")!=string::npos||value.find("Xisha")!=string::npos||value.find("Nansha")!=string::npos||value.find("nine-dash")!=string::npos){st.review++;if(st.alerts.size()<20)st.alerts.push_back(key+": "+value);}}}
}
void scanTile(const vector<uint8_t>& raw,const string &expected,int z,uint64_t x,uint64_t y,Stats& st){Slice root{raw.data(),raw.data()+raw.size()};F fld;bool found=false;while(next(root,fld)){if(fld.n!=3)continue;if(fld.w!=2)throw runtime_error("bad Tile.layers wire");string lname;int version=0,extent=4096;vector<Slice> feats;vector<string> keys,values;Slice layer=fld.s;F it;while(next(layer,it)){if(it.n==1&&it.w==2)lname=str(it.s);else if(it.n==2&&it.w==2)feats.push_back(it.s);else if(it.n==3&&it.w==2)keys.push_back(str(it.s));else if(it.n==4&&it.w==2){Slice value=it.s;F k;string text;bool seen=false;while(next(value,k)){if(k.n>=1&&k.n<=7){if(seen)throw runtime_error("value duplicate");seen=true;int ew=k.n==1?2:(k.n==2?5:(k.n==3?1:0));if(k.w!=ew)throw runtime_error("invalid typed value");if(k.n==1)text=str(k.s);}}if(!seen)throw runtime_error("empty typed value");values.push_back(text);}else if(it.n==5&&it.w==0)extent=it.v;else if(it.n==15&&it.w==0)version=it.v;}
  if(lname!=expected||version!=2||extent<1||extent>65536)throw runtime_error("source-layer mismatch");found=true;for(auto f:feats)feature(f,keys,values,extent,z,x,y,st);
 }if(!found)throw runtime_error("missing source-layer");}
int main(int argc,char**argv){try{if(argc<3||argc>5){cerr<<"usage: fast_scan <PMTiles> <source_layer> [start=0] [count=all]\n";return 2;}string file=argv[1],layer=argv[2];size_t start=argc>=4?stoull(argv[3]):0,count=argc>=5?stoull(argv[4]):0;ifstream in(file,ios::binary);if(!in)throw runtime_error("no input");array<uint8_t,127>h{};in.read((char*)h.data(),h.size());if(in.gcount()!=127||string((char*)h.data(),7)!="PMTiles"||h[7]!=3)throw runtime_error("not v3");uint64_t ro=read64(h.data()+8),rl=read64(h.data()+16),lo=read64(h.data()+40),tl=read64(h.data()+56),expected=read64(h.data()+80);int internal=h[97],compression=h[98];auto roots=directory(section(in,ro,rl),internal);vector<Entry> tiles;for(auto e:roots){if(e.run)tiles.push_back(e);else{auto leaves=directory(section(in,lo+e.off,e.len),internal);tiles.insert(tiles.end(),leaves.begin(),leaves.end());}}if(tiles.size()!=expected)throw runtime_error("wrong total index count");if(start>=tiles.size())throw runtime_error("invalid start");size_t stop=count?min(tiles.size(),start+count):tiles.size();Stats st;array<uint64_t,23> zooms{};for(size_t i=start;i<stop;i++){auto e=tiles[i];if(e.run!=1)throw runtime_error("shared tile data not handled");int z;uint64_t x,y;zxy(e.id,z,x,y);zooms[z]++;auto raw=section(in,tl+e.off,e.len);if(compression==2)raw=ungzip(raw);else if(compression!=1)throw runtime_error("tile compression unsupported");try{scanTile(raw,layer,z,x,y,st);}catch(const exception&ex){throw runtime_error("index="+to_string(i)+" tile="+to_string(e.id)+" "+ex.what());}if((i-start+1)%2048==0)cerr<<layer<<" "<<(i+1)<<"/"<<tiles.size()<<" entries\n";}
  cout<<setprecision(15)<<"{\"archive\":\""<<jsonescape(file)<<"\",\"source_layer\":\""<<jsonescape(layer)<<"\",\"index_entries\":"<<tiles.size()<<",\"start\":"<<start<<",\"end\":"<<stop<<",\"point\":"<<st.features[0]<<",\"line\":"<<st.features[1]<<",\"polygon\":"<<st.features[2]<<",\"vertices\":"<<st.vertices<<",\"paths\":"<<st.paths<<",\"name_fields\":"<<st.names<<",\"review_hits\":"<<st.review<<",\"bbox\":["<<st.box.w<<","<<st.box.s<<","<<st.box.e<<","<<st.box.n<<"],\"zooms\":[";for(int i=0;i<23;i++){if(i)cout<<",";cout<<zooms[i];}cout<<"],\"examples\":[";for(size_t i=0;i<st.alerts.size();i++){if(i)cout<<",";cout<<"\""<<jsonescape(st.alerts[i])<<"\"";}cout<<"],\"p0_status\":\"BLOCKED\"}"<<endl;
}catch(const exception&ex){cerr<<"SCAN_FAILED: "<<ex.what()<<"\n";return 1;}return 0;}
